-- Phase 7 research report record (07-FIX6b, ADR-0030, RSRCH-03). Generated by
-- `pnpm exec drizzle-kit generate --name research_report_records` on top of the journal
-- (position 0012, after 0011_research_source_records), then hand-edited as 0007 and 0011 were:
--   1. `IF NOT EXISTS` added to the CREATE TABLE, because drizzle-kit does not emit it and a
--      partly set-up store must never fail a service start on this file.
--
-- One row per research run that published a report: the run, the report's note id and a SHA-256
-- digest of the report's served-relevant content (findings with their kinds, quotes and
-- citations, the partial flag, the unavailable sources, the source total and the cited source
-- references). 0011 binds a source to a run; this binds the REPORT to the run, so a report edited
-- in place after the run (a claim reworded, a kind flipped, another real quote swapped in) no
-- longer matches and its quotes are not shown as verified.
--
-- The columns hold a run id, a note id, a SHA-256 and an ISO instant ONLY. No report text, title
-- or model output column exists and none may be added; `migration-report-record.audit.test.ts`
-- walks the column names and the stored values.
--
-- Applied files are never renumbered, renamed or edited (ADR-0018, M-1).
CREATE TABLE IF NOT EXISTS `research_report_records` (
	`job_run_id` text PRIMARY KEY NOT NULL,
	`report_note_id` text NOT NULL,
	`content_digest` text NOT NULL,
	`recorded_at` text NOT NULL
);
